19	/// The project's single `get_it` instance — exactly one DI container exists
20	/// (architecture spine). Every feature's `registerXFeature()` registers
21	/// through this same `sl`, never a second container.
22	final sl = GetIt.instance;
23	
24	/// Bootstraps core infrastructure: loads `.env`, then registers
25	/// `FlutterSecureStorage`, `Dio` (configured with the header + retry
26	/// interceptors) and `ApiClient` through `sl` — the `dio` +
27	/// `flutter_secure_storage` + `get_it` integration spike this story proves
28	/// before anything else is built on top of it.
29	Future<void> setupCoreDependencies() async {
30	  await dotenv.load(fileName: '.env');
31	
32	  final functionsBaseUrl = dotenv.get('FUNCTIONS_BASE_URL');
33	  final supabaseAnonKey = dotenv.get('SUPABASE_ANON_KEY');
34	
35	  sl.registerLazySingleton<FlutterSecureStorage>(
36	    () => const FlutterSecureStorage(),
37	  );
38	
39	  sl.registerLazySingleton<AccessTokenProvider>(
40	    () => SecureStorageAccessTokenProvider(sl<FlutterSecureStorage>()),
41	  );
42	
43	  sl.registerLazySingleton<UrlBuilder>(() => UrlBuilder(functionsBaseUrl));
44	
45	  // Story 1.5 — `dispose:` wires `SessionExpiryNotifier.dispose()` into
46	  // `get_it`'s own reset lifecycle, same rationale as `SessionRepository`'s
47	  // own registration below. Registration order here is cosmetic, not
48	  // load-bearing: `registerLazySingleton` only builds its instance on first
49	  // `sl<T>()` access, so `ApiClient`'s factory can resolve this dependency
50	  // correctly regardless of which of the two is registered first.
51	  sl.registerLazySingleton<SessionExpiryNotifier>(
52	    () => SessionExpiryNotifierImpl(),
53	    dispose: (notifier) => notifier.dispose(),
54	  );
55	
56	  sl.registerLazySingleton<Dio>(() {
57	    final dio = Dio(
58	      BaseOptions(
59	        // Design note (docs/input is silent on exact numbers): a stalled
60	        // connection must still fail instead of hanging indefinitely.
61	        connectTimeout: const Duration(seconds: 10),
62	        receiveTimeout: const Duration(seconds: 30),
63	        sendTimeout: const Duration(seconds: 30),
64	      ),
65	    );
66	    dio.interceptors.add(
67	      HeaderInterceptor(
68	        anonKey: supabaseAnonKey,
69	        accessTokenProvider: sl<AccessTokenProvider>(),
70	      ),
71	    );
72	    dio.interceptors.add(RetryInterceptor(dio));
73	    return dio;
74	  });
75	
76	  sl.registerLazySingleton<ApiClient>(
77	    () => ApiClient(
78	      dio: sl<Dio>(),
79	      urlBuilder: sl<UrlBuilder>(),
80	      sessionExpiryNotifier: sl<SessionExpiryNotifier>(),
81	    ),
82	  );
83	
84	  registerAuthFeature();
85	  registerVaultFeature();
86	  registerAccountFeature();
87	
88	  // Story 3.1 — the app's first `hive_ce` usage: `initFlutter()` must
89	  // complete before `registerEntriesFeature()` opens its box (Code Map).
90	  await Hive.initFlutter();
91	  await registerEntriesFeature();
92	  registerCaptureFeature();
93	}
94	
95	/// Test/teardown helper — resets the single `get_it` instance so each test
96	/// bootstraps its own clean registrations.
97	Future<void> resetCoreDependencies() => sl.reset();
